import datasets
import numpy as np
from scipy.optimize import curve_fit
import warnings
warnings.filterwarnings('ignore')

ds = datasets.load_from_disk('/app/data')
groups = ds.unique('group')

def sigmoid(f, a, b, c, d):
    return a / (1.0 + b * np.power(np.maximum(f, 1e-10), c)) + d

def power_offset(f, a, b, c):
    return a * np.power(np.maximum(f, 1e-10), b) + c

def quadratic_log(x, a, b, c):
    return a * x**2 + b * x + c

# Try sigmoid with MANY initial conditions for each group
print("=== Sigmoid fits ===")
sigmoid_params = {}
for g in groups:
    subset = [row for row in ds if row['group'] == g]
    y = np.array([r['brier_score'] for r in subset])
    f = np.array([r['flops'] for r in subset])

    best_rmse = 999
    best_p = None

    # Generate many initial conditions
    init_conds = []
    for a0 in [-1.0, -0.5, -0.3, -0.1, 0.1, 0.3, 0.5, 1.0]:
        for b0 in [0.1, 0.5, 1.0, 2.0, 5.0, 10.0]:
            for c0 in [-2.0, -1.0, -0.5, 0.3, 0.5, 1.0, 2.0]:
                for d0 in [-0.5, -0.3, -0.1, 0.0, 0.1]:
                    init_conds.append((a0, b0, c0, d0))

    for p0 in init_conds:
        try:
            popt, _ = curve_fit(sigmoid, f, y, p0=p0, maxfev=5000)
            yp = sigmoid(f, *popt)
            rmse = np.sqrt(np.mean((y - yp)**2))
            if rmse < best_rmse and np.all(np.isfinite(popt)):
                best_rmse = rmse
                best_p = popt
        except:
            pass

    sigmoid_params[g] = {'a': float(best_p[0]), 'b': float(best_p[1]), 'c': float(best_p[2]), 'd': float(best_p[3]), 'rmse': float(best_rmse)}
    print(f"  {g}: a={best_p[0]:.4f}, b={best_p[1]:.4f}, c={best_p[2]:.4f}, d={best_p[3]:.4f}, RMSE={best_rmse:.6f}")

# Also try power_offset with many initial conditions
print("\n=== Power offset fits ===")
po_params = {}
for g in groups:
    subset = [row for row in ds if row['group'] == g]
    y = np.array([r['brier_score'] for r in subset])
    f = np.array([r['flops'] for r in subset])

    best_rmse = 999
    best_p = None

    for a0 in [-1.0, -0.5, -0.3, -0.1, -0.01, 0.01, 0.1, 0.3, 0.5, 1.0]:
        for b0 in [-3.0, -2.0, -1.0, -0.5, -0.3, -0.1, 0.1, 0.5]:
            for c0 in [-0.7, -0.5, -0.3, -0.1, 0.0, 0.1]:
                try:
                    popt, _ = curve_fit(power_offset, f, y, p0=(a0, b0, c0), maxfev=5000)
                    yp = power_offset(f, *popt)
                    rmse = np.sqrt(np.mean((y - yp)**2))
                    if rmse < best_rmse and np.all(np.isfinite(popt)):
                        best_rmse = rmse
                        best_p = popt
                except:
                    pass

    po_params[g] = {'a': float(best_p[0]), 'b': float(best_p[1]), 'c': float(best_p[2]), 'rmse': float(best_rmse)}
    print(f"  {g}: a={best_p[0]:.4f}, b={best_p[1]:.4f}, c={best_p[2]:.4f}, RMSE={best_rmse:.6f}")

# Compare
print("\n=== Comparison ===")
print(f"{'Group':<40s} {'Sigmoid RMSE':>14s} {'PO RMSE':>14s}")
for g in groups:
    print(f"{g:<40s} {sigmoid_params[g]['rmse']:>14.6f} {po_params[g]['rmse']:>14.6f}")

import json
with open('/app/sigmoid_params.json', 'w') as f:
    json.dump(sigmoid_params, f, indent=2)
with open('/app/po_params.json', 'w') as f:
    json.dump(po_params, f, indent=2)
